from pathlib import Path
import base64

root = Path.cwd()

required = [
    root / "app/(portal)/admin/gathering/page.tsx",
    root / "app/(portal)/admin/gathering/actions.ts",
    root / "components/portal/admin-context-panel.tsx",
]

for path in required:
    if not path.exists():
        raise SystemExit(
            f"Could not find {path.relative_to(root)}. "
            "Run this script from the sepulchria-portal repository root."
        )

payloads = {'app/(portal)/admin/gathering/actions.ts': '', 'app/(portal)/admin/gathering/page.tsx': '', 'components/admin/gathering-admin-ui.tsx': '', 'components/admin/gathering-context-panel.tsx': ''}

for relative, content64 in payloads.items():
    target = root / relative
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(base64.b64decode(content64))

context_path = root / "components/portal/admin-context-panel.tsx"
context = context_path.read_text(encoding="utf-8")

import_anchor = 'import { HouseOfChancesContextPanel } from "@/components/admin/house-of-chances-context-panel";\n'
import_new = import_anchor + 'import { GatheringContextPanel } from "@/components/admin/gathering-context-panel";\n'
if 'GatheringContextPanel' not in context:
    if import_anchor not in context:
        raise SystemExit("Could not find HouseOfChancesContextPanel import anchor.")
    context = context.replace(import_anchor, import_new, 1)

mode_anchor = '  | "house_of_chances"\n  | "crafting_recipes"'
mode_new = '  | "house_of_chances"\n  | "gathering"\n  | "crafting_recipes"'
if '  | "gathering"\n' not in context:
    if mode_anchor not in context:
        raise SystemExit("Could not find ContextMode anchor.")
    context = context.replace(mode_anchor, mode_new, 1)

path_anchor = '  if (pathname === "/admin/house-of-chances") {\n    return "house_of_chances";\n  }\n\n  if (\n'
path_new = '  if (pathname === "/admin/house-of-chances") {\n    return "house_of_chances";\n  }\n\n  if (pathname === "/admin/gathering") {\n    return "gathering";\n  }\n\n  if (\n'
if 'pathname === "/admin/gathering"' not in context:
    if path_anchor not in context:
        raise SystemExit("Could not find admin context pathname anchor.")
    context = context.replace(path_anchor, path_new, 1)

render_anchor = '  if (mode === "house_of_chances") {\n    return (\n      <HouseOfChancesContextPanel />\n    );\n  }\n\n  if (mode === "codex") {\n'
render_new = '  if (mode === "house_of_chances") {\n    return (\n      <HouseOfChancesContextPanel />\n    );\n  }\n\n  if (mode === "gathering") {\n    return (\n      <GatheringContextPanel />\n    );\n  }\n\n  if (mode === "codex") {\n'
if 'mode === "gathering"' not in context:
    if render_anchor not in context:
        raise SystemExit("Could not find admin context render anchor.")
    context = context.replace(render_anchor, render_new, 1)

context_path.write_text(context, encoding="utf-8")

print("Gathering admin UX patch applied successfully.")
print("Updated:")
print(" - app/(portal)/admin/gathering/actions.ts")
print(" - app/(portal)/admin/gathering/page.tsx")
print(" - components/portal/admin-context-panel.tsx")
print("Created:")
print(" - components/admin/gathering-admin-ui.tsx")
print(" - components/admin/gathering-context-panel.tsx")
print()
print("Next: npm run build")
